@startuml

class Hospital {
  + Name : string
}

class ExaminationType {
  + Name : string
}

class Problem {
  + Name : string
}

class TreatmentPlan {
  + Name : string
}

class Doctor {
  + Name : string
}

class Patient {
  + Name : string
}

class Diagnosis {
  + Date : date
}

class ActualTreatment {
  + Date : date
}

class MedicalAction {
  + Description : string
}

class Examination {
  + Date : date
}

Hospital "1" -- "*" ExaminationType : has permission for
Hospital "1" -- "*" Doctor : employs
Hospital "1" -- "*" Diagnosis : hosts
Hospital "1" -- "*" ActualTreatment : hosts
Hospital "1" -- "*" Examination : hosts

Problem "1" -- "*" TreatmentPlan : defines
TreatmentPlan "*" -- "*" ExaminationType : advises

Doctor "1" -- "*" Diagnosis : poses
Doctor "1" -- "*" ActualTreatment : defines
Patient "1" -- "*" Diagnosis : receives
Patient "1" -- "*" ActualTreatment : receives

ActualTreatment "1" -- "*" Examination : consists of
ActualTreatment "1" -- "*" MedicalAction : consists of
ActualTreatment "0..1" -- "1" TreatmentPlan : based on
Examination "*" -- "1" ExaminationType : is of type
Examination "0..1" -- "0..1" Hospital : performed at

@enduml

